INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Trends > Veränderungen von Einsatzfeldern für IT-Systemen aufgrund technischer, wirtschaftlicher sowie gesellschaftlicher Entwicklungen feststellen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Veränderungen von Einsatzfeldern für IT-Systeme ausschließlich durch technische Entwicklungen bedingt sein?', 2, '[{"text": "Nein", "correct": true, "because": "Wirtschaftliche und gesellschaftliche Faktoren spielen ebenfalls eine Rolle"}, {"text": "Ja", "correct": false, "because": "Mehrere Faktoren beeinflussen Einsatzfelder"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Veränderungen von Einsatzfeldern für IT-Systeme immer mit neuen Technologien einhergehen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bestehende Technologien können neue Einsatzfelder finden"}, {"text": "Ja", "correct": false, "because": "Neue Anwendungen sind unabhängig möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Haben gesellschaftliche Entwicklungen wie Homeoffice-Trends die Einsatzfelder für IT-Systeme beeinflusst?', 2, '[{"text": "Ja", "correct": true, "because": "Remote-Arbeit fördert Kommunikations- und Cloud-Tools"}, {"text": "Nein", "correct": false, "because": "Gesellschaftliche Trends sind maßgeblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können wirtschaftliche Entwicklungen die Einsatzfelder für IT-Systeme einschränken?', 2, '[{"text": "Ja", "correct": true, "because": "Kostendruck kann Investitionen in IT reduzieren"}, {"text": "Nein", "correct": false, "because": "Wirtschaftliche Faktoren wirken limitierend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Veränderungen von Einsatzfeldern für IT-Systeme immer vorhersehbar?', 2, '[{"text": "Nein", "correct": true, "because": "Unvorhergesehene Entwicklungen können überraschen"}, {"text": "Ja", "correct": false, "because": "Dynamik macht Prognosen schwierig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche technische Entwicklung hat die Einsatzfelder für IT-Systeme im Gesundheitswesen stark verändert?', 2, '[{"text": "Telemedizin", "correct": true, "because": "Ermöglicht Fernbehandlung"}, {"text": "Blockchain", "correct": false, "because": "Weniger dominant im Gesundheitswesen"}, {"text": "Augmented Reality", "correct": false, "because": "Nischenanwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher gesellschaftliche Trend hat die Einsatzfelder für IT-Systeme im Bildungsbereich erweitert?', 3, '[{"text": "Online-Lernen", "correct": true, "because": "E-Learning-Plattformen boomen"}, {"text": "Urbanisierung", "correct": false, "because": "Wenig direkter Einfluss"}, {"text": "Alternde Bevölkerung", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche wirtschaftliche Entwicklung fördert neue Einsatzfelder für IT-Systeme in Unternehmen?', 2, '[{"text": "Globalisierung", "correct": true, "because": "Erfordert vernetzte Systeme"}, {"text": "Inflation", "correct": false, "because": "Eher einschränkend"}, {"text": "Steuersenkungen", "correct": false, "because": "Indirekter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Einsatzfeld für IT-Systeme wurde durch technische Entwicklungen wie IoT erweitert?', 2, '[{"text": "Smart Homes", "correct": true, "because": "Vernetzung von Geräten"}, {"text": "Buchhaltung", "correct": false, "because": "Weniger IoT-bezogen"}, {"text": "Marketing", "correct": false, "because": "Andere Technologien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Veränderung von Einsatzfeldern für IT-Systeme am wenigsten direkt?', 2, '[{"text": "Politische Stabilität", "correct": true, "because": "Indirekter Einfluss"}, {"text": "Technologische Innovation", "correct": false, "because": "Direkter Treiber"}, {"text": "Gesellschaftliche Bedürfnisse", "correct": false, "because": "Direkt relevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche technischen Entwicklungen verändern die Einsatzfelder für IT-Systeme?', 4, '[{"text": "Cloud Computing", "correct": true, "because": "Ermöglicht flexible Nutzung"}, {"text": "Künstliche Intelligenz", "correct": true, "because": "Automatisiert Prozesse"}, {"text": "5G-Netzwerke", "correct": true, "because": "Verbessert Konnektivität"}, {"text": "Manuelle Datenbanken", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesellschaftlichen Entwicklungen beeinflussen die Einsatzfelder für IT-Systeme?', 3, '[{"text": "Digitalisierung der Bildung", "correct": true, "because": "Fördert E-Learning"}, {"text": "Homeoffice-Trend", "correct": true, "because": "Erhöht Bedarf an Remote-Tools"}, {"text": "Nachhaltigkeitsbewusstsein", "correct": true, "because": "Treibt grüne IT"}, {"text": "Geburtenrate", "correct": false, "because": "Wenig direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche wirtschaftlichen Entwicklungen fördern neue Einsatzfelder für IT-Systeme?', 4, '[{"text": "Outsourcing", "correct": true, "because": "Erfordert IT-Unterstützung"}, {"text": "E-Commerce-Wachstum", "correct": true, "because": "Braucht Online-Plattformen"}, {"text": "Automatisierung", "correct": true, "because": "Steigert Effizienz"}, {"text": "Steuererhöhungen", "correct": false, "because": "Eher hinderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche neuen Einsatzfelder für IT-Systeme sind durch technische Entwicklungen entstanden?', 3, '[{"text": "Smart Cities", "correct": true, "because": "IoT und Big Data"}, {"text": "Telemedizin", "correct": true, "because": "Fernüberwachung"}, {"text": "Autonome Fahrzeuge", "correct": true, "because": "KI und Sensorik"}, {"text": "Manuelle Buchführung", "correct": false, "because": "Keine neue Entwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren erschweren die Feststellung von Veränderungen der Einsatzfelder für IT-Systeme?', 3, '[{"text": "Schnelle technologische Änderungen", "correct": true, "because": "Dynamik erschwert Prognosen"}, {"text": "Unvorhersehbare gesellschaftliche Trends", "correct": true, "because": "Schwer planbar"}, {"text": "Wirtschaftliche Unsicherheiten", "correct": true, "because": "Beeinflusst Investitionen"}, {"text": "Stabile Marktbedingungen", "correct": false, "because": "Erleichtert eher"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Technische Entwicklungen wie IoT erweitern Einsatzfelder für IT-Systeme. b) Gesellschaftliche Entwicklungen sind irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IoT ja, Gesellschaft wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Wirtschaftliche Trends wie E-Commerce fördern IT-Einsatzfelder. b) Neue Einsatzfelder erfordern immer neue Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "E-Commerce ja, Hardware nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Homeoffice hat die Einsatzfelder für Kommunikations-Tools erweitert. b) Wirtschaftliche Rezessionen fördern IT-Investitionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Homeoffice ja, Rezessionen eher nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Telemedizin ist ein neues Einsatzfeld durch technische Trends. b) Gesellschaftliche Trends haben keinen Einfluss auf IT-Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Telemedizin ja, Gesellschaft relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Veränderungen von Einsatzfeldern können unvorhersehbar sein. b) Technische Entwicklungen sind der einzige Treiber.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unvorhersehbar ja, nicht nur Technik"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

